import { zoom, zoomIdentity } from 'd3-zoom';
import { select } from 'd3-selection';
const pane = document.querySelector('#pane');
const samples = [];
const behavior = zoom().extent([[0,0],[1280,720]]).scaleExtent([0.5,2]).on('zoom', e => {
  pane.style.transform = `translate(${e.transform.x}px, ${e.transform.y}px) scale(${e.transform.k})`;
  samples.push({ at: performance.now(), event: e.sourceEvent?.type ?? 'control', x: e.transform.x, y: e.transform.y, zoom: e.transform.k });
});
const selection = select(pane).call(behavior);
selection.call(behavior.transform, zoomIdentity.scale(0.8187307530779818));
document.querySelector('button').onclick = () => selection.call(behavior.scaleBy, 1/1.2);
window.samples = samples;

