const { chromium } = require(process.cwd() + '/node_modules/@playwright/test');
const fs = require('node:fs');
(async () => {
const browser = await chromium.launch();
const page = await browser.newPage({viewport:{width:1280,height:720}});
await page.setContent('<style>body{margin:0}#pane{width:1280px;height:720px;position:absolute;transform-origin:0 0}button{position:fixed;bottom:0;z-index:2}</style><div id="pane"></div><button>Zoom out</button>');
await page.addScriptTag({path:'/tmp/plan138/d3/reference.bundle.js'});
const before = await page.evaluate(() => window.samples.at(-1));
await page.getByRole('button').click();
await page.waitForTimeout(50);
const afterControl = await page.evaluate(() => window.samples.at(-1));
await page.mouse.dblclick(640,360);
await page.waitForTimeout(50);
const at50 = await page.evaluate(() => window.samples.at(-1));
await page.waitForTimeout(50);
const at100 = await page.evaluate(() => window.samples.at(-1));
await page.waitForTimeout(200);
const result = await page.evaluate(() => ({final:window.samples.at(-1),samples:window.samples}));
fs.writeFileSync('/tmp/plan138/d3-reference.json',JSON.stringify({version:'d3-zoom@3.0.0',before,afterControl,at50,at100,...result},null,2));
await browser.close();
})();
